// Each chapter adds a distinct comparison to the two fictional recorded walks.
function transcript(note, language) {
  const inputs = base.filter(n => n.group === 'kyoto');
  const opening = language === 'zh' ? '这是一段为 Clipbind 演示写的虚构视频转写。地点、店铺与价格都是样本，用来展示长转写如何被检索和整理。\n\n' : 'This fictional transcript was written for the Clipbind demo. Venues, prices and locations are invented to demonstrate searching and binding long video notes.\n\n';
  const observations = language === 'zh' ? [
    '出发前我把这段路拆成到站、找出口、步行、停留和返程五段。地图上挨着的两个点，实际可能隔着台阶和围墙。把出口名字写在离线笔记里，比截一张整个城区的地图更好用。',
    '这一段不能只记门票。等待、寄包和买水也占时间。我会在抵达前把钱包拿出来，先看入口告示，确认今天开放的门，再去排队。省下的十分钟留给院子，而不是塞进第四个景点。',
    '如果早上起晚了，就删去一个停留点，别把之后所有行程往后推。预约只固定一项，其他按距离串联。下雨时优先走有顶棚的路，石阶上的落叶比平地更容易滑。',
    '同行的人走路快慢不同，所以每走一段就留一个能坐下的地方。不要在狭窄路口停着商量下一站。先走到宽一点的地方，再打开地图。背包放身前，别挡住其他人的通道。',
    '预算表里我把住宿总额和个人支出分开。房间是两人共用，门票和车费则按人算。同一个金额如果先记整间房、后面又各算一遍，就会把总价翻高。',
    '返程路线在去程时就看好。不是每一条路都适合拖箱子，也不是每一个出口都有电梯。到终点还要算走去站台的时间，不能把地图上的到站时刻当作坐上车的时刻。',
    '点餐前先看最后点单时间，再看营业结束时间。菜单写着豆腐或蘑菇，也可能用了鱼汤或鸡汤。饮食限制直接问清楚，别从图标猜。若不能调整，就用事先记下的另一家。',
    '我把当日地图、店铺门口和菜单分开放。景色照片不用送进整理步骤，只有文字难以替代的路线图才留下。整理完仍能回到原笔记，查当时为什么选这条路。'
  ] : [
    'Before leaving, divide this leg into arrival, finding the exit, walking, the visit and returning. Nearby map pins can hide stairs or walls. Save the exit name offline instead of relying on a screenshot of the entire district.',
    'Admission is only one part of the visit. Waiting, bag storage and water stops take time too. Check the entrance notice and today’s open gate before joining a queue. Give the time saved to the courtyard instead of adding another attraction.',
    'If the morning starts late, remove one stop instead of shifting every later activity. Fix one reservation and connect the other places by distance. In rain, prioritise covered paths and watch wet leaves on steps.',
    'People walk at different speeds, so plan a place to sit between legs. Do not stop at a narrow junction to discuss the next turn. Reach a wider spot, then open the map and keep bags clear of passing walkers.',
    'Separate the whole room bill from personal spending. Two travellers share the room, while tickets and rides are per person. Counting the full room and then adding each person’s half again inflates the budget.',
    'Check the way home on the outward journey. Not every lane suits a wheeled case and not every station exit has a lift. The path to the platform still takes time. Reaching the station pin is different from boarding.',
    'Check last orders before the closing hour. Tofu or mushrooms can still use fish or chicken stock. Ask directly about dietary needs instead of guessing from icons. Keep another venue ready if the kitchen cannot adapt.',
    'Keep daily maps, storefront images and menus separate. Scenery does not need image analysis. Retain only a route diagram whose layout cannot be replaced by text. A bound guide should still lead back to the original reasoning.'
  ];
  const chapters = [];
  inputs.forEach((input, i) => {
    chapters.push((language === 'zh' ? '第' + (i + 1) + '段，' : 'Leg ' + (i + 1) + ', ') + input.title[language] + '。\n' + input.body[language]);
    const rotation = note.demoKey === 'kyoto-4' ? i : i + 3;
  for (let j = 0; j < (note.demoKey === 'kyoto-4' ? 5 : 1); j++) chapters.push(observations[(rotation + j) % observations.length]);
  });
  return opening + chapters.join('\n\n');
}
base.filter(note => note.group === 'kyoto').forEach((note, i) => {
  const diagram = { 2: 'kyoto-route', 3: 'kyoto-transit', 9: 'kyoto-walk' }[i];
  note.images = [diagram ? `assets/demo-covers/${diagram}.svg` : note.demoCover];
  if (i < 11) note.images.push('assets/demo-covers/kyoto-route.svg');
});
const sets = {};
for (const language of ['zh', 'en']) sets[language] = base.map(note => ({ ...note, title: note.title[language], body: note.body[language], tags: note.tags.map(tag => language === 'zh' ? tag : englishTags[tag] || tag), transcript: note.isVideo ? transcript(note, language) : '', images: note.images.map(file => file.replace(/(kyoto-(?:route|transit|walk))\.svg$/, '$1-' + language + '.svg')) }));

const sections = {
  kyoto: [
    [pair('五天的顺序', 'The five-day shape'), pair('五天住同一处。第一天北山三寺，第二天东岸步道与旧街，第三天西谷竹径，第四天南城市场与手作，第五天早市后返程。每天只固定一项预约，午后留 90 分钟。河岸小舍在河町青石路 8 号，双人间 ¥9,800／晚，不含早餐，离地铁 6 分钟，入住 15:00、退房 10:00。四晚共 ¥39,200，两人平分。松灯旅舍 ¥8,600／晚，房间小，机场接驳更方便。河岸去车站多留 15 分钟，行李可先寄存。21:00 后河岸很安静，拖箱经过石板路时放轻声音。', 'Keep one base for five days. Visit northern temples, east-bank lanes, West Valley bamboo, South Town market and crafts, then the morning market before departure. Book one timed activity daily and leave 90 minutes after lunch. Riverbank House, 8 Bluestone Road, Kawamachi, is ¥9,800 a double per night without breakfast, six minutes from the metro. Check in at 3pm and out at 10am, with bag storage available. Four nights cost ¥39,200, shared between two. Pine Lantern Hostel is ¥8,600 nightly with smaller rooms and easier airport transfers. Allow 15 extra minutes to the station from the riverside. It is quiet after 9pm, so keep rolling bags quiet on the stone lanes.'), [3, 2, 1]],
    [pair('寺院与步道，按地理位置串起来', 'Temples and walks, grouped by place'), pair('北山日 7:00 从纸灯寺开始，北山区杉巷 12 号，¥600。北山站走 12 分钟，从东门台阶进，8:15 前最安静。再走 18 分钟到枫井院，9:00 开门、¥400，最后小川寺，现金 ¥300。东岸从青石桥到柳岸口 3.2 公里，约 80 分钟，有四处休息点，主路平缓，旧街支路前 1.1 公里有台阶。黄绳封住的低道不要进，终点到地铁再留 12 分钟。第三天 9:00 前从西谷站北口进竹径，主路 1.8 公里，石桥向东下山，回站共 3.6 公里。西门多 120 级台阶，避开大行李。站前买水，桥边两张长椅可休息，雨后防滑。', 'Start the northern day at Paper Lantern Temple at 7am, 12 Cedar Lane, Kitayama, ¥600. Walk 12 minutes from the station via the eastern steps. It is quiet before 8:15. Continue 18 minutes to Maple Well Hall, open 9am, ¥400, then Little Stream Temple, ¥300 cash. The east bank runs 3.2km from Bluestone Bridge to Willow Exit in about 80 minutes with four rest points. The main path is gentle. The old-lane detour has steps in its first 1.1km. Respect yellow-rope closures and allow 12 minutes onward to the metro. Reach West Valley’s north exit before 9am on day three. Walk the 1.8km bamboo path, then turn east downhill at Stone Bridge for a 3.6km station loop. The west gate adds 120 steps. Buy water at the station, rest on the two bridge benches and watch wet ground.'), [4, 1, 10, 7]],
    [pair('交通与费用', 'Transport and the budget'), pair('演示票价中，巴士 ¥230、地铁 ¥260、一日券 ¥1,100，当天约五次适用乘车才划算。北山三次巴士 ¥690，东岸两次地铁 ¥520，南城四次巴士 ¥920，都不用买券。西谷往返列车 ¥720，不在券内。第五天步行。上车前备零钱，地图在站外看。每人交通总预算 ¥2,850，含 ¥720 机场接驳、不含跨城往返。每天餐饮 ¥3,200，五天 ¥16,000；三寺 ¥1,300，木器馆 ¥700。住宿分摊 ¥19,600，加 ¥3,000 机动，每人约 ¥43,450，购物与 ¥2,800 打磨课另算。', 'At the fictional fares, buses cost ¥230, metro rides ¥260 and a day pass ¥1,100. Around five included rides make a pass worthwhile. Three northern buses cost ¥690, two east-bank metro rides ¥520 and four South Town buses ¥920, so skip the pass on those days. The ¥720 West Valley return train is excluded. Walk on day five. Prepare change before boarding and check maps at stops. Allow ¥2,850 per person for transport, including the ¥720 airport shuttle but excluding intercity travel. Food is ¥3,200 daily, ¥16,000 across five days. Three temples cost ¥1,300 and the museum ¥700. Half the room bill is ¥19,600. With ¥3,000 contingency, budget about ¥43,450 per person before shopping or the optional ¥2,800 class.'), [4, 11]],
    [pair('吃什么，什么时候去', 'Food, addresses and hours'), pair('青瓦食堂在河町灯巷 6 号，17:00–21:00、20:15 最后点单，周三休息，豆腐定食 ¥1,450。蘑菇饭含鱼汤，饮食限制需直接问。井边面屋在井路 14 号，11:30–19:30，荞麦面 ¥980、海带汤 ¥250。慢火小馆在桥东 3 号，晚餐 ¥2,100，仅十席，前一天订。西谷桥东小食亭 10:00 开，现金买饭团 ¥220、味噌汤 ¥180。东岸苔庭茶室 10:30–16:30，周四休息，焙茶 ¥520、米糕 ¥380。雨天去纸窗咖啡，11:00–18:00、周一休息，拿铁 ¥580、南瓜吐司 ¥680。', 'Blue Tile Kitchen, 6 Lantern Lane, Kawamachi, serves a ¥1,450 tofu set, 5–9pm, last orders 8:15pm, closed Wednesday. Mushroom rice contains fish stock, so ask about dietary needs. Wellside Noodles, 14 Well Road, opens 11:30am–7:30pm with ¥980 soba and ¥250 kelp soup. Slow Flame, 3 East Bridge, has ten seats and ¥2,100 dinner. Book the day before. East Bridge Snack Hut in West Valley opens 10am, taking cash for ¥220 rice balls and ¥180 miso soup. Moss Garden Teahouse opens 10:30am–4:30pm, closed Thursday, with ¥520 roasted tea and ¥380 rice cake. Rainy-day Paper Window Coffee opens 11am–6pm, closed Monday. A latte is ¥580 and pumpkin toast ¥680.'), [5, 7, 10, 6]],
    [pair('雨天和市场的备选', 'Rain and market alternatives'), pair('大雨把东岸换成木器馆，10:00–17:00、¥700，周二闭馆。约看 70 分钟，大伞寄存，展厅禁拍。走八分钟到纸窗咖啡，再去有顶棚的南城市场，从南城站返回。市场 9:30 后开档、16:00 多数收摊，周日只开一半。青叶茶摊 40 克焙茶 ¥900，可试喝一次；豆坊热豆乳 ¥300，自带杯减 ¥20；木匙工作室手刻匙 ¥1,600，14:00 打磨课 ¥2,800，提前两天约。陶杯逛第二圈再买，出口可回收纸箱。', 'In heavy rain, swap the east bank for the Woodcraft Museum, ¥700, 10am–5pm, closed Tuesday. Allow 70 minutes, store large umbrellas and keep cameras out of galleries. Walk eight minutes to Paper Window Coffee, then use covered South Town Market and return from its station. Stalls open from 9:30am and mostly close at 4pm. Half open on Sunday. Green Leaf Tea sells 40g roasted tea for ¥900 with one tasting. Bean House hot soy milk is ¥300, ¥20 off with your own cup. Wooden Spoon Studio’s carved spoons cost ¥1,600 and its 2pm sanding class ¥2,800, booked two days ahead. Buy cups on the second circuit and recycle cardboard at the exit.'), [6, 8]],
    [pair('随身带什么', 'What to carry'), pair('20 升背包加小箱就够。穿防滑鞋，伞放侧袋，随身 ¥5,000 现金。离线保存住宿地址、返程车次和每天一张路线图。充电宝与水壶分袋，照片和视频每晚备份，陶杯用衣服包，别压相机。鞋湿了可向旅舍前台借报纸。走一段留一处休息，地图在宽路口看，不在窄巷挡路，拥挤时把背包移到身前。晚起就删一个点，不用让一天的行程都追着时间跑。', 'Use a 20-litre daypack and small case. Wear grippy shoes, keep an umbrella in the side pocket and carry ¥5,000 cash. Save the lodging address, return service and a map for each day offline. Separate the power bank from water. Back up photos and video nightly. Wrap cups in clothes and protect the camera. Ask the hostel for newspaper to dry shoes. Plan rest points, check maps in wider spaces and move your backpack to the front in crowds. If you start late, drop a stop instead of rushing the whole day.'), [9, 6, 10]],
    [pair('最后一早与返程', 'The last morning and departure'), pair('周六 7:30–10:30 去河町早市。谷口烘焙红豆卷 ¥280，9:00 前常卖完，但不要为它错过返程。行李留住宿处，10:00 退房前取。河町口到机场接驳站走 15 分钟，车费 ¥720，提前 25 分钟到站。若市场不开，车站松灯早餐铺 6:30 开，粥套餐 ¥650。所有地点、店铺与票价均为虚构演示信息。', 'Kawamachi Morning Market opens Saturdays, 7:30–10:30am. Valley Bakery’s ¥280 red-bean rolls often sell out before 9am, but protect the return journey. Collect stored bags before 10am check-out. Walk 15 minutes from Kawamachi exit to the airport shuttle stop, pay ¥720 and arrive 25 minutes early. If the market is closed, station-side Pine Lantern Breakfast opens at 6:30am with a ¥650 porridge set. All venues, locations and fares are fictional demo information.'), [12]]
  ],
  food: [
    [pair('先选时间，再选店', 'Choose a time, then a table'), pair('周六早一点去燕麦窗，灯塔街 18 号，8:00–15:00，9:30 前较好入座，10:30 后约等 25 分钟。窗边两人桌，四人先约。周日燕麦窗不开，8:00 可以去桦木煎饼屋，海风路 9 号，14:00 收，10:00 前到，只收借记卡。想晚一点，苔色餐桌在杉木街 42 号，周末 9:00–16:00。雨天订红砖早餐房，枫巷 31 号，周末 8:30–14:30，前一天可订 9:00 或 13:00，迟到保留十分钟，室外等位处没有顶棚。', 'On Saturday, start early at Oat Window, 18 Lantern Street, 8am–3pm. Arrive before 9:30am for easier seating or expect roughly 25 minutes after 10:30. Window tables seat two. Book for four. It closes Sunday, when Birch Pancake House, 9 Sea Breeze Road, opens 8am–2pm. Arrive before 10am and bring a debit card. Moss Table, 42 Cedar Street, is a later option, 9am–4pm both days. In rain, reserve Red Brick Breakfast, 31 Maple Lane, open 8:30am–2:30pm. Book a 9am or 1pm slot the day before. Tables are held ten minutes and the waiting area has no roof.'), [1, 8, 5, 2, 4]],
    [pair('菜单与饮食限制', 'Menus and dietary needs'), pair('燕麦窗两张荞麦薄饼 C$18，水果加 C$4，咖啡 C$5；想咸味选这里。无麸质面糊共用烤盘，过敏先问。桦木三张厚薄饼 C$22，含苹果酱，咖啡 C$5，两人分食需各点饮料。苔色豆腐炒蛋 C$19、番茄 C$6、燕麦拿铁 C$6，可点单时把黄油换橄榄油；蘑菇汤含鸡汤，不能只看叶子图标。轮椅走苔色侧门，正门有一级台阶。红砖蛋盘 C$21，茶 C$4，伞放门口桶里。', 'Oat Window serves two buckwheat pancakes for C$18, fruit for C$4 extra and coffee for C$5. Choose it for savoury food. Gluten-free batter shares the griddle, so ask about allergies. Birch serves three thick pancakes with apple sauce for C$22 and coffee for C$5. Sharing requires two drinks. Moss Table’s tofu scramble is C$19, tomatoes C$6 and oat latte C$6. Ask when ordering to replace butter with olive oil. Its mushroom soup uses chicken stock. The leaf symbol does not promise vegetarian food. Use the side door for step-free access. Red Brick’s egg plate costs C$21 and tea C$4. Leave umbrellas in the entrance bucket.'), [1, 5, 2, 4]],
    [pair('两个人的预算', 'A budget for two'), pair('燕麦窗两份薄饼两杯咖啡小计 C$46，预留税和小费 C$12，总计约 C$58。苔色两份炒蛋两杯燕麦拿铁小计 C$50，预留 C$12，总计 C$62。红砖两份蛋盘两杯茶 C$50，预留 C$13，总计 C$63。这些只是演示预算，不能当税率，停车另算，付款前可问清账单。', 'At Oat Window, two pancake plates and coffees total C$46 before a C$12 tax and tip allowance, about C$58. Two scrambles and oat lattes at Moss Table total C$50 plus C$12, about C$62. Two egg plates and teas at Red Brick total C$50 plus C$13, about C$63. These fictional planning allowances are not tax rates. Parking is extra. Ask about bill details before payment.'), [7, 1, 2, 4]],
    [pair('吃完走走，再喝一杯', 'Walk after eating, then have coffee'), pair('从燕麦窗向南走六分钟到灯塔河道，沿水 1.6 公里到白石小桥，约半小时，终点有洗手间。雨天改走平行铺装路，多 200 米，避开湿木板。回程公交在杉木街路口。终点再走七分钟到回声咖啡，港湾小径 7 号，8:00–17:00、周二休息。手冲 C$6，鸡蛋吐司 C$14，续滤泡 C$3。周末 11:00–14:00 不接笔记本，其他时段可用长桌，仅两处插座；窗边桌限两人，电话到外面打。店铺、地址、时间与价格均为虚构，真实出门前查当天营业。', 'Walk six minutes south from Oat Window to Lantern Canal, then follow the water for 1.6km to White Stone Bridge, around half an hour with public toilets at the finish. In rain, use the parallel paved route, 200m longer, to avoid the wet boardwalk. The return bus is at Cedar Street junction. Continue seven minutes to Echo Coffee, 7 Harbour Lane, 8am–5pm, closed Tuesday. Pour-over is C$6, egg toast C$14 and a second filter coffee C$3. Laptops are excluded from 11am–2pm on weekends. Use the communal table at other times, with two power points. Window tables seat two. Take calls outside. Venues, addresses, hours and prices are fictional. Check current hours before a real visit.'), [6, 3, 8]]
  ]
};

const guides = {};
for (const language of ['zh', 'en']) {
  guides[language] = {};
  for (const key of ['kyoto', 'food']) {
    const input = sets[language].filter(n => n.group === key);
    const raw = {
      title: key === 'kyoto' ? pair('京都五日', 'Kyoto in five days')[language] : pair('温哥华周末早午餐', 'A Vancouver brunch weekend')[language],
      topic: key === 'kyoto' ? pair('京都旅行', 'Kyoto travel')[language] : pair('温哥华美食', 'Vancouver food')[language],
      summary: key === 'kyoto' ? pair('把十二篇笔记放到同一张行程里，从北山三寺走到河町早市。路线、票价、吃饭与雨天备选一起留好。所有地点与价格均为虚构演示。', 'Twelve notes become one walkable plan, from the northern temples to the morning market, with fares, meals and rainy-day alternatives kept together. All places and prices are fictional.')[language] : pair('八篇笔记整理成一个不用赶路的周末。先选能坐下的时间，再看菜单、两人预算与饭后步道。店铺均为虚构。', 'Eight notes become an unhurried weekend, with seating times, menus, a budget for two and a walk after eating. Every venue is fictional.')[language],
      sections: sections[key].map(([heading, content, indices]) => ({ heading: heading[language], content: content[language], source_indices: indices })),
      keep_images: key === 'kyoto' ? ['10-1'] : []
    };
    const saved = { ...raw, id: `demo-guide-${key}`, demoKey: key, sections: raw.sections.map(s => ({ heading: s.heading, content: s.content, sources: s.source_indices.map(n => ({ title: input[n - 1].title, url: input[n - 1].url })) })), sourceNoteIds: input.map(n => n.id), sourceUrls: input.map(n => n.url), images: key === 'kyoto' ? [input[9].images[0]] : [], imagesRepo: [], lang: language, runAt: authoredAt, savedAt: authoredAt, model: 'AI-authored demo', trace: { imagesRead: input.reduce((sum, note) => sum + note.images.length, 0), transcriptCharsUsed: input.reduce((sum, note) => sum + Math.min((note.transcript || "").length, 8000), 0), inputNotes: input.length } };
    guides[language][key] = saved;
    fs.writeFileSync(path.join(root, 'demo', `${key}.${language}.json`), JSON.stringify(saved, null, 2) + '\n');
    const context = { window: { XHS: { i18n: { lang: language } } }, URLSearchParams, location: { search: '?demo=1' } };
    vm.createContext(context);
    vm.runInContext(fs.readFileSync(path.join(root, 'js/ai.js'), 'utf8').replace('  X.ai = {', '  X.promptRun = { systemPrompt: systemPrompt, postsBlock: postsBlock, schema: SCHEMA };\n  X.ai = {'), context);
    const prompt = context.window.XHS.promptRun;
    const record = { method: 'Authored by the AI coding agent in this build, following the exact application binding prompt. No API call was made. Fictional inputs and original SVG diagrams only.', language, authoredAt, system: prompt.systemPrompt(), userText: `Here are ${input.length} saved items (Xiaohongshu posts/videos, Bilibili videos):\n\n` + prompt.postsBlock(input), images: input.flatMap((note, i) => note.images.map((file, j) => ({ label: `[image ${i + 1}-${j + 1}]`, file }))), schema: prompt.schema, inputIds: input.map(n => n.id), rawOutput: raw, outputSHA256: crypto.createHash('sha256').update(JSON.stringify(raw)).digest('hex') };
    fs.writeFileSync(path.join(root, 'demo', `${key}.${language}.prompt-run.json`), JSON.stringify(record, null, 2) + '\n');
  }
}
